"""Generate command references from the installed Typer metadata."""

from __future__ import annotations

import argparse
import json
import os
import subprocess
import sys
from pathlib import Path


def render(language: str) -> str:
    os.environ["DDK_LANG"] = language
    from typer.main import get_command

    from ddk.cli import app

    korean = language == "ko"
    lines = [
        "# 명령 참조" if korean else "# Command reference",
        "",
        "<!-- Generated by scripts/generate_commands.py. -->",
        "",
    ]

    def visit(command, route):
        lines.extend(["## " + " ".join(["ddk", *route]), "", command.help or "", ""])
        if command.params:
            lines.extend(
                [
                    "| 인자·옵션 | 자료형 | 기본값 | 설명 |"
                    if korean
                    else "| Argument / option | Type | Default | Description |",
                    "| --- | --- | --- | --- |",
                ]
            )
            for parameter in command.params:
                names = [*getattr(parameter, "opts", []), *getattr(parameter, "secondary_opts", [])]
                label = ", ".join(names) or parameter.name
                default = (
                    "required" if parameter.required else json.dumps(parameter.default, default=str)
                )
                help_text = (
                    (getattr(parameter, "help", "") or "").replace("|", "\\|").replace("\n", " ")
                )
                lines.append(f"| `{label}` | `{parameter.type.name}` | `{default}` | {help_text} |")
            lines.append("")
        for name, child in sorted(getattr(command, "commands", {}).items()):
            visit(child, [*route, name])

    visit(get_command(app), [])
    return "\n".join(lines)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    parser.add_argument("--language", choices=["en", "ko"])
    args = parser.parse_args()
    if args.language:
        print(render(args.language), end="")
        return 0
    root = Path(__file__).resolve().parents[1]
    stale = []
    for lang, name in [("en", "COMMANDS.md"), ("ko", "COMMANDS.ko.md")]:
        text = subprocess.run(
            [sys.executable, str(Path(__file__).resolve()), "--language", lang],
            capture_output=True,
            text=True,
            check=True,
            cwd=root,
        ).stdout
        path = root / "docs" / name
        if args.check:
            if not path.exists() or path.read_text() != text:
                stale.append(name)
        else:
            path.write_text(text)
    if stale:
        print("stale command references: " + ", ".join(stale))
    return bool(stale)


if __name__ == "__main__":
    raise SystemExit(main())
